CREATE TABLE scrims (id INTEGER PRIMARY KEY,guild_id INTEGER,title TEXT,status TEXT,points_per_win INTEGER,end_mode TEXT,target_value INTEGER,formation_mode TEXT,league_completed_at TEXT,league_end_reason TEXT,panel_channel_id INTEGER,panel_message_id INTEGER,waiting_channel_id INTEGER,created_at TEXT,ended_at TEXT);
CREATE TABLE participants (scrim_id INTEGER,member_id INTEGER,member_name TEXT,primary_role TEXT,primary_position TEXT,secondary_role TEXT,secondary_position TEXT,captain_willing INTEGER,preferred_team_no INTEGER,fixed_role TEXT,registered_at TEXT);
CREATE TABLE teams (id INTEGER PRIMARY KEY,scrim_id INTEGER,team_no INTEGER,slot_key TEXT,captain_id INTEGER,points INTEGER,voice_channel_id INTEGER,withdrawn_at TEXT);
CREATE TABLE team_members (team_id INTEGER,slot INTEGER,member_id INTEGER,member_name TEXT,role TEXT,position TEXT,is_substitute INTEGER);
CREATE TABLE substitutes (scrim_id INTEGER,member_id INTEGER,member_name TEXT,roles_json TEXT,positions_json TEXT,registered_at TEXT);
CREATE TABLE fixtures (id INTEGER PRIMARY KEY,scrim_id INTEGER,round_no INTEGER,match_no INTEGER,team_a_id INTEGER,team_b_id INTEGER,status TEXT,reported_by INTEGER,proposed_winner_id INTEGER,disputed_by INTEGER,disputed_winner_id INTEGER,confirmed_by INTEGER,winner_team_id INTEGER,match_id INTEGER,result_type TEXT,forfeited_team_id INTEGER,completed_at TEXT);
CREATE TABLE matches (id INTEGER PRIMARY KEY,scrim_id INTEGER,team_a_id INTEGER,team_b_id INTEGER,winner_team_id INTEGER,points_awarded INTEGER,reversed INTEGER,created_at TEXT,fixture_id INTEGER);
CREATE TABLE substitutions (id INTEGER PRIMARY KEY,scrim_id INTEGER,team_id INTEGER,slot INTEGER,outgoing_id INTEGER,outgoing_name TEXT,incoming_id INTEGER,incoming_name TEXT,role TEXT,position TEXT,created_at TEXT);
